def ensure_arabic_font():
    """Retourne une police Unicode disponible, en la restaurant depuis le code si besoin."""
    candidates = [
        APP_DIR / "DejaVuSans.ttf",
        Path("/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf"),
        Path("/usr/share/fonts/truetype/dejavu/DejaVuSansCondensed.ttf"),
    ]
    for candidate in candidates:
        if candidate.is_file():
            return candidate
    # Extraction dans /tmp : aucune dépendance à un fichier placé à côté de app.py.
    embedded_path = Path(tempfile.gettempdir()) / "FGEArabic-DejaVuSans.ttf"
    if not embedded_path.is_file() or embedded_path.stat().st_size < 100000:
        font_bytes = zlib.decompress(base64.b64decode(_EMBEDDED_ARABIC_FONT_ZLIB_B64))
        embedded_path.write_bytes(font_bytes)
    return embedded_path
