def date_fr_complete(d):
    mois = ["janvier", "février", "mars", "avril", "mai", "juin", "juillet", "août", "septembre", "octobre", "novembre", "décembre"]
    return f"{JOURS_FR[d.weekday()]} {d.day} {mois[d.month-1]} {d.year}"

def remplir_tableau_assiduite(doc, date_debut, date_fin):
    try:
        debut = date.fromisoformat(str(date_debut)[:10])
        fin = date.fromisoformat(str(date_fin)[:10])
    except Exception:
        return
    table = next((t for t in doc.tables if len(t.rows) >= 16 and len(t.columns) >= 3 and "Observation" in t.cell(0,2).text), None)
    if table is None:
        return
    current = debut
    for idx in range(1, min(16, len(table.rows))):
        if current > fin:
            table.cell(idx,1).text = "—"
            table.cell(idx,2).text = "—"
            continue
        table.cell(idx,1).text = date_fr_complete(current)
        holiday = FERIES_ALGERIE.get(current.isoformat())
        if current.weekday() in (4,5):
            label = "Vendredi" if current.weekday() == 4 else "Samedi"
            table.cell(idx,2).text = f"Non comptabilisé — {label}"
        elif holiday:
            table.cell(idx,2).text = f"Non comptabilisé — {holiday}"
        else:
            table.cell(idx,2).text = ""
        current += timedelta(days=1)

ANNEES_FR = {"1": "première", "2": "deuxième", "3": "troisième", "4": "quatrième", "5": "cinquième"}
SPECIALITES_INGENIEUR = {"EI": "électricité industrielle", "RSE": "réseaux et sources d'énergie"}
SPECIALITES_MASTER = {"RE": "réseaux électriques", "ER": "énergies renouvelables",
                      "ME": "machines électriques", "CE": "commandes électriques"}

def _maj(s):
    return s[:1].upper() + s[1:]

def decode_promotion(promotion):
    """Décode un code de promotion pour remplir TOUS les endroits du document généré.

    ING<3|4|5><EI|RSE> : ingénieur ; M<1|2><RE|ER|ME|CE> : Master ; M<1|2>MCIL : Master en électrotechnique ;
    MCIL<2|3> : Licence en électrotechnique.
    Clés renvoyées : inscrit (« Inscrit (e) en … »), specialite (« Spécialité : … »),
    diplome_stage (« obtention de diplôme … » de l'article 2), passage (fin de la phrase de l'article 1).
    """
    code = norm_promo(promotion)
    m = re.fullmatch(r"ING([345])(EI|RSE)", code)
    if m:
        annee, spec = ANNEES_FR[m.group(1)], SPECIALITES_INGENIEUR[m.group(2)]
        return {"inscrit": f"{annee} année Ingénieur", "specialite": _maj(spec), "diplome_stage": "d'ingénieur",
                "passage": f"en {annee} année en vue de l’obtention du diplôme d'ingénieur en {spec}."}
    m = re.fullmatch(r"M([12])(RE|ER|ME|CE)", code)
    if m:
        annee, spec = ANNEES_FR[m.group(1)], SPECIALITES_MASTER[m.group(2)]
        return {"inscrit": f"{annee} année Master", "specialite": _maj(spec), "diplome_stage": "de master",
                "passage": f"en {annee} année en vue de l’obtention du diplôme Master en {spec}."}
    m = re.fullmatch(r"M([12])MCIL", code)
    if m:
        annee = ANNEES_FR[m.group(1)]
        return {"inscrit": f"{annee} année Master ({code})", "specialite": "Électrotechnique", "diplome_stage": "de master",
                "passage": f"en {annee} année ({code}) en vue de l’obtention du diplôme Master en électrotechnique."}
    m = re.fullmatch(r"MCIL([23])", code)
    if m:
        annee = ANNEES_FR[m.group(1)]
        return {"inscrit": f"{annee} année Licence (MCIL)", "specialite": "Électrotechnique", "diplome_stage": "de licence",
                "passage": f"en {annee} année MCIL en vue de l’obtention du diplôme de Licence en électrotechnique."}
    return {"inscrit": promotion or "", "specialite": promotion or "", "diplome_stage": "de master",
            "passage": f"en vue de l’obtention du diplôme ({promotion})." if promotion else "en vue de l’obtention du diplôme."}

def stage_passage_for_promotion(promotion):
    """Fin de la phrase « Le stage concerne l'étudiant(e) … » selon la promotion."""
    return decode_promotion(promotion)["passage"]

def _iter_paragraphs(container):
    for paragraph in getattr(container, "paragraphs", []):
        yield paragraph
    for table in getattr(container, "tables", []):
        for row in table.rows:
            for cell in row.cells:
                yield from _iter_paragraphs(cell)

def fix_stage_passage(doc, full_name, promotion):
    """Réécrit la fin du paragraphe « Le stage concerne l'étudiant(e) … » avec l'année et la spécialité exactes."""
    nbsp = "\xa0"
    passage = stage_passage_for_promotion(promotion)
    for paragraph in _iter_paragraphs(doc):
        found = re.search(r"Le stage concerne l.étudiant\(e\)", paragraph.text)
        if not found:
            continue
        new_text = f"{paragraph.text[:found.end()]}{nbsp}{full_name} inscrit (e){nbsp}{passage}"
        runs = paragraph.runs
        if runs:  # on garde la mise en forme du premier run
            runs[0].text = new_text
            for extra in runs[1:]:
                extra.text = ""
        else:
            paragraph.text = new_text

def fix_attestation_inscription(doc, promotion):
    """Attestation de stage : « Inscrit (e) en <année> en vue de l'obtention du diplôme …, à la Faculté de Génie Electrique … »."""
    passage = stage_passage_for_promotion(promotion).rstrip(".")
    for paragraph in _iter_paragraphs(doc):
        found = re.match(r"^(\s*)Inscrit\s*\(e\)\s+à la Faculté de Génie Electrique de l.Université de Sidi Bel Abbes(.*)$",
                         paragraph.text, flags=re.S)
        if not found:
            continue
        new_text = (f"{found.group(1)}Inscrit (e) {passage}, à la Faculté de Génie Electrique "
                    f"de l’Université de Sidi Bel Abbes{found.group(2)}")
        runs = paragraph.runs
        if runs:
            runs[0].text = new_text
            for extra in runs[1:]:
                extra.text = ""
        else:
            paragraph.text = new_text

def build_three_stage_documents(request_data, student, nb_participants=1):
    """Remplit le modèle institutionnel (assiduité + convention + attestation) pour UN SEUL étudiant.

    Toutes les informations personnelles (nom, prénom, matricule, naissance, adresse, e-mail,
    téléphone, promotion) proviennent de l'étudiant concerné, jamais du demandeur principal.
    """
    if not CONVENTION_TEMPLATE.is_file():
        raise FileNotFoundError("Le modèle conventions.docx est absent du dépôt GitHub.")
    doc = Document(str(CONVENTION_TEMPLATE))
    r = request_data
    s = student or {}
    remplir_tableau_assiduite(doc, r.get("date_debut", ""), r.get("date_fin", ""))
    nom, prenom = s.get("nom", "") or "", s.get("prenom", "") or ""
    full_name = f"{nom} {prenom}".strip()
    company = r.get("entreprise", "")
    address = r.get("adresse_entreprise", "")
    wilaya = r.get("wilaya_entreprise", "")
    start, end = r.get("date_debut", ""), r.get("date_fin", "")
    domicile = s.get("adresse_domicile") or ""
    matricule = s.get("matricule") or ""
    promotion = s.get("promotion") or r.get("promotion", "")
    info = decode_promotion(promotion)
    replacements = {
        "ablasaoudi99@gmail.com": s.get("email", ""),
        "666187646": s.get("telephone", ""),
        "Nom : saoudi": f"Nom : {nom}",
        "Nom\xa0: saoudi": f"Nom : {nom}",
        "Prénom : abla": f"Prénom : {prenom}",
        # Ne jamais remplacer l'adresse du domicile par la wilaya de résidence.
        "Adresse : Hassi Messaoud-Ouargla": f"Adresse : {domicile}",
        "Adresse\xa0: Hassi Messaoud-Ouargla": f"Adresse : {domicile}",
        "2025-2026": "2026-2027",
        "2 éme année Licence": info["inscrit"],
        "Electrotechnique": "Electrotechnique",
        "MCIL Electrotechnique": info["specialite"],
        # Article 2 : le diplôme dépend du cycle (ingénieur / master / licence).
        "obtention de diplôme de master": f"obtention de diplôme {info['diplome_stage']}",
        # Date de signature de la convention : date réelle de génération du document.
        "22-04-2026": datetime.now().strftime("%d-%m-%Y"),
        "22/03/2026": start, "04/04/2026": end,
        "Sonatrach/division Production-Direction Régionale Ouagla-hassi Messaoud": company,
        "Sonatrach/division Production-Direction Régionale": company,
        "EL BGUEL.BP 113": address, "HASSI MESSAOUD /OUARGLA": wilaya,
        "saoudi abla": full_name,
        "Inscrit (e) sous le Numéro.   …………………   .pour l’année universitaire 2026-2027:":
            f"Inscrit (e) sous le Numéro.   {matricule}   .pour l’année universitaire 2026-2027:",
        "Inscrit (e) sous le Numéro.   …………………   .pour l’année universitaire 2025-2026:":
            f"Inscrit (e) sous le Numéro.   {matricule}   .pour l’année universitaire 2026-2027:",
        "09/09/2005": s.get("date_naissance", ""),
        "Mchedallah /Bouira": s.get("lieu_naissance", ""),
        "sontrach/division Production-Direction Régionale": company,
        "(nombres d’étudiants)": str(max(1, int(nb_participants or 1))),
    }
    def walk_paragraphs(container):
        for paragraph in getattr(container, "paragraphs", []):
            _replace_docx_paragraph(paragraph, replacements)
        for table in getattr(container, "tables", []):
            for row in table.rows:
                for cell in row.cells:
                    walk_paragraphs(cell)
    walk_paragraphs(doc)
    fix_stage_passage(doc, full_name, promotion)
    fix_attestation_inscription(doc, promotion)

    # Identifier explicitement la nature du stage dans le dossier documentaire
    # généré par le Chef de département (un fichier regroupant les formulaires).
    if str(r.get("type_demande", "Stage rémunéré")).strip() == "Stage non rémunéré":
        title = "DEMANDE DE STAGE PROFESSIONNEL NON RÉMUNÉRÉ"
        anchor = next((p for p in doc.paragraphs
                       if "Attestation d’Assiduité" in p.text or "Attestation d'Assiduité" in p.text), None)
        if anchor is not None:
            title_paragraph = anchor.insert_paragraph_before(title)
            title_paragraph.alignment = 1  # centré
            for run in title_paragraph.runs:
                run.bold = True
                run.font.size = Pt(14)
                run.font.color.rgb = RGBColor(23, 63, 95)
        else:
            title_paragraph = doc.paragraphs[0].insert_paragraph_before(title)
            title_paragraph.alignment = 1
            for run in title_paragraph.runs:
                run.bold = True
                run.font.size = Pt(14)
                run.font.color.rgb = RGBColor(23, 63, 95)

    out = io.BytesIO()
    doc.save(out)
    return out.getvalue()



VISIT_TEMPLATE = APP_DIR / "Visite.docx"
AVIS_CHEF_FAV = "Avis favorable"
AVIS_CHEF_DEF = "Avis défavorable"

def _replace_docx_text_in_paragraph(paragraph, replacements):
    original = paragraph.text
    updated = original
    for old, new in replacements.items():
        updated = updated.replace(old, str(new or ""))
    if updated != original:
        if paragraph.runs:
            paragraph.runs[0].text = updated
            for run in paragraph.runs[1:]:
                run.text = ""
        else:
            paragraph.text = updated

def _walk_docx_paragraphs(container):
    for paragraph in getattr(container, "paragraphs", []):
        yield paragraph
    for table in getattr(container, "tables", []):
        for row in table.rows:
            for cell in row.cells:
                yield from _walk_docx_paragraphs(cell)

